const magnet = document.getElementById('magnet');
const container = document.getElementById('magnet-container');
let isDragging = false;
let startY = 0;
let magnetTop = 130;
let lastMagnetTop = 130;
let lastTime = Date.now();

const minY = 10;
const maxY = 130;

function initMagnet() {
  magnetTop = 130;
  magnet.style.top = magnetTop + 'px';
  updateDisplay();
}

function updateDisplay() {
  // 磁铁位置
  document.getElementById('magnetPos').textContent = (150 - magnetTop) + ' px';

  // 计算磁通量变化（根据距离）
  const distance = 150 - magnetTop; // 0-140px
  const fluxRate = (magnetTop - lastMagnetTop) / (Date.now() - lastTime + 1); // 变化率

  if (Math.abs(fluxRate) > 0.01) {
    if (fluxRate < 0) {
      document.getElementById('fluxChange').textContent = '↑ 增加';
      document.getElementById('fluxChange').style.color = '#e74c3c';
      document.getElementById('currentDir').textContent = '顺时针';
      document.getElementById('currentDir').style.color = '#3498db';
      document.getElementById('principle').textContent = '增反（N极靠近，感应N极）';
      document.getElementById('principle').style.color = '#e74c3c';
      // 指针偏转
      document.getElementById('needle').style.transform = 'rotate(-30deg)';
    } else {
      document.getElementById('fluxChange').textContent = '↓ 减少';
      document.getElementById('fluxChange').style.color = '#3498db';
      document.getElementById('currentDir').textContent = '逆时针';
      document.getElementById('currentDir').style.color = '#e74c3c';
      document.getElementById('principle').textContent = '减同（N极远离，感应S极）';
      document.getElementById('principle').style.color = '#3498db';
      // 指针偏转
      document.getElementById('needle').style.transform = 'rotate(30deg)';
    }
  } else {
    document.getElementById('fluxChange').textContent = '— 稳定';
    document.getElementById('fluxChange').style.color = '#7f8c8d';
    document.getElementById('currentDir').textContent = '— 无';
    document.getElementById('currentDir').style.color = '#7f8c8d';
    document.getElementById('principle').textContent = '磁通量不变，无感应电流';
    document.getElementById('principle').style.color = '#7f8c8d';
    document.getElementById('needle').style.transform = 'rotate(0deg)';
  }

  // 上报Stage结果
  window.HeurisStage.emit('experiment-result', {
    type: 'electromagnetic-induction',
    magnetPosition: magnetTop,
    fluxChange: fluxRate > 0 ? 'decreasing' : fluxRate < 0 ? 'increasing' : 'stable',
    currentDirection: fluxRate < 0 ? 'clockwise' : fluxRate > 0 ? 'counter-clockwise' : 'none',
    knowledgePoint: '电磁感应原理 / 楞次定律'
  });

  lastMagnetTop = magnetTop;
  lastTime = Date.now();
}

magnet.addEventListener('mousedown', (e) => {
  isDragging = true;
  startY = e.clientY - magnetTop;
  magnet.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', (e) => {
  if (!isDragging) return;
  magnetTop = e.clientY - startY;
  magnetTop = Math.max(minY, Math.min(maxY, magnetTop));
  magnet.style.top = magnetTop + 'px';
  updateDisplay();
});

document.addEventListener('mouseup', () => {
  isDragging = false;
  magnet.style.cursor = 'grab';
});

document.getElementById('resetBtn').addEventListener('click', () => {
  initMagnet();
});

// Touch support
magnet.addEventListener('touchstart', (e) => {
  isDragging = true;
  startY = e.touches[0].clientY - magnetTop;
});

document.addEventListener('touchmove', (e) => {
  if (!isDragging) return;
  magnetTop = e.touches[0].clientY - startY;
  magnetTop = Math.max(minY, Math.min(maxY, magnetTop));
  magnet.style.top = magnetTop + 'px';
  updateDisplay();
});

document.addEventListener('touchend', () => {
  isDragging = false;
});

// 初始化
initMagnet();

